head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDisabled]<br/>파라미터에 맞게 특정 단위의 비활성화(disabled) 상태를 true/false 로 반환합니다.",
    "validation" : [
        "type 파라미터값이 'column' 이면 Column 단위의 비활성화(disabled) 상태를 조회해야 합니다.",
        "colInfo(필수) 파라미터로 type 파라미터값이 'column' 일때 비활성화(disabled) 상태를 조회할 Column 과 Cell 의 인덱스를 설정할 수 있어야 합니다. (Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Column 0 → setColumnDisabled(true) / Column 2 → setColumnDisabled(false) / 그 외 Column 은 미설정 / Column 1 은 숨겨진 상태 (숨겨진 Column 도 인덱스에 포함)"', '', 'label1');

    // 조건 설정 (disabled/readonly Cell 을 배경색으로 구분: disabled=회색, readonly=연노랑)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김 (숨겨진 Column 도 인덱스에 포함됨)
    target1.setColumnVisible(1, false);

    // Column(column) 단위 disabled 설정 (type='column' 검증)
    target1.setColumnDisabled(0, true);    // Column 0 단위 true
    target1.setColumnDisabled(2, false);   // Column 2 단위 false
}



scwin.btn_getDisabled_onclick = function () {
    let colInfo = Number(par_colInfo.getValue());

    // column 단위는 type, colInfo(인덱스) 전달
    let rtn = target1.getDisabled("column", colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('column', " + colInfo + ") : " + rtn);
}
